Lemma lor_192 a : 0 <= a < 32 -> Z.lor a 192 = a + 192.
Proof. try hcb. try hsb. intros Ha. change 192 with (3 * 2 ^ 6). rewrite (lor_small_shl 3 6 a) by lia. lia. Qed.
